import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.ClgMjOt7.js";const _=JSON.parse('{"title":"検索とお気に入りタグ (ウォッチリスト)","description":"作品検索、フィルター機能、ウォッチリストの使い方","frontmatter":{"title":"検索とお気に入りタグ (ウォッチリスト)","description":"作品検索、フィルター機能、ウォッチリストの使い方"},"headers":[],"relativePath":"user/search.md","filePath":"user/search.md","lastUpdated":1789105872000}'),l={name:"user/search.md"};function o(i,a,n,h,c,d){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="検索とお気に入りタグ-ウォッチリスト" tabindex="-1">検索とお気に入りタグ (ウォッチリスト) <a class="header-anchor" href="#検索とお気に入りタグ-ウォッチリスト" aria-label="Permalink to &quot;検索とお気に入りタグ (ウォッチリスト)&quot;">​</a></h1><hr><h2 id="さがす" tabindex="-1">さがす <a class="header-anchor" href="#さがす" aria-label="Permalink to &quot;さがす&quot;">​</a></h2><p>検索画面では、以下の方法で作品を探せます。</p><ul><li><strong>タグ検索</strong>: 見たいジャンルやキャラクターのタグで検索します。</li><li><strong>完全一致検索</strong>: そのタグにぴったり合う作品だけを表示します。</li><li><strong>タイトル・説明文検索</strong>: 作品名や作者の説明文に入っている言葉で探します。</li><li><strong>ユーザー検索</strong>: 作者名や Pixiv ID で絵師さんを探します。</li></ul><hr><h2 id="絞り込み-フィルター" tabindex="-1">絞り込み (フィルター) <a class="header-anchor" href="#絞り込み-フィルター" aria-label="Permalink to &quot;絞り込み (フィルター)&quot;">​</a></h2><ul><li><strong>ソート</strong>: 「投稿が新しい順」「投稿が古い順」「人気順」に並び替えできます。</li><li><strong>ブクマ数フィルター</strong>: 「1000users入り」「5000users入り」など、人気の作品だけに絞り込めます。</li><li><strong>期間指定</strong>: 「24時間以内」「1週間以内」などの投稿時期で絞り込めます。</li></ul><hr><h2 id="ウォッチリスト-お気に入りタグ" tabindex="-1">ウォッチリスト (お気に入りタグ) <a class="header-anchor" href="#ウォッチリスト-お気に入りタグ" aria-label="Permalink to &quot;ウォッチリスト (お気に入りタグ)&quot;">​</a></h2><p>よく検索する好きなタグを<strong>ウォッチリスト</strong>に登録しておくと便利です。</p><ul><li>検索結果から「★ ウォッチリストに追加」をタップすると登録されます。</li><li>ウォッチリスト画面を開くと、新しく投稿された作品の件数が表示され、1 タップで最新の投稿をチェックできます。</li></ul>',12)])])}const g=r(l,[["render",o]]);export{_ as __pageData,g as default};
